def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import numpy as np
    if horizon <= 0:
        return []
    y = np.asarray(history, dtype=float)
    y = y[np.isfinite(y)]
    if len(y) == 0:
        return [0.0] * horizon
    n = len(y)
    f = frequency.lower()
    p = 24 if 'hour' in f else (7 if 'day' in f else (12 if 'month' in f else max(2, min(24, n // 4))))
    if n < 2 * p:
        return [float(y[-1])] * horizon
    def run(train, steps, a, b, g, phi):
        m = len(train)
        first = train[:p]
        level = float(np.mean(first))
        if m >= 2 * p:
            trend = float((np.mean(train[p:2 * p]) - np.mean(first)) / p)
        else:
            trend = 0.0
        season = np.asarray(first - level, dtype=float).copy()
        for t in range(p, m):
            idx = t % p
            old_level = level
            level = a * (train[t] - season[idx]) + (1.0 - a) * (level + phi * trend)
            trend = b * (level - old_level) + (1.0 - b) * phi * trend
            season[idx] = g * (train[t] - level) + (1.0 - g) * season[idx]
        result = []
        for j in range(steps):
            if abs(1.0 - phi) < 1e-12:
                trend_sum = trend * (j + 1)
            else:
                trend_sum = trend * phi * (1.0 - phi ** (j + 1)) / (1.0 - phi)
            result.append(level + trend_sum + season[(m + j) % p])
        return np.asarray(result)
    validation = min(p, max(4, n // 5))
    cut = n - validation
    grid = [0.2, 0.5, 0.8]
    best = (0.5, 0.2, 0.5, 0.9)
    best_error = float('inf')
    for a in grid:
        for b in [0.1, 0.3]:
            for g in grid:
                for phi in [0.8, 0.95]:
                    pred = run(y[:cut], validation, a, b, g, phi)
                    error = float(np.median(np.abs(pred - y[cut:])))
                    if np.isfinite(error) and error < best_error:
                        best_error = error
                        best = (a, b, g, phi)
    raw = run(y, horizon, *best)
    spread = float(np.quantile(y, 0.95) - np.quantile(y, 0.05)) + 1e-8
    raw = np.clip(raw, float(np.min(y)) - spread, float(np.max(y)) + spread)
    if float(np.mean(y >= 0.0)) > 0.98:
        raw = np.maximum(raw, 0.0)
    return [float(v) if np.isfinite(v) else float(y[-1]) for v in raw]
